mapper.select:
select * from order_detail where order_id in
#{orderId}
order by order_id, id

select od.dish_id as item_id, sum(od.number) as monthly_sales
from order_detail od inner join orders o on od.order_id = o.id
where o.status = 5
  and o.order_time >= #{begin}
  and o.order_time < #{end}
  and od.dish_id in

    #{id}

group by od.dish_id

select od.setmeal_id as item_id, sum(od.number) as monthly_sales
from order_detail od inner join orders o on od.order_id = o.id
where o.status = 5
  and o.order_time >= #{begin}
  and o.order_time < #{end}
  and od.setmeal_id in

    #{id}

group by od.setmeal_id
